chaoKhach();',phan:[['void','Hàm không trả về giá trị.']],quyTac:['Ví dụ trong bài đặt hàm trước main.','Cần lời gọi thì hàm mới thực hiện.']},
      {ten:'THAM SỐ CỦA HÀM',mau:'void inSoLy(int soLy) {
    cout << soLy;
}
// Trong main:
inSoLy(3);',phan:[['int soLy','Tham số nhận số nguyên từ lời gọi.'],['3','Giá trị truyền vào ở lần gọi này.']]},
      {ten:'TRẢ VỀ KẾT QUẢ',mau:'int tinhTien(int soLy) {
