    if(step.kind!=='stage')continue;
    const spec=syntax[LESSON.number]?.[i];if(spec)step.lesson=step.lesson.replace('<div class="pair-view">',cuPhap(spec)+'<div class="pair-view">');
  }
  if(LESSON.number===3){
    const step=LESSON.steps[0];
